FILE: app/src/orbit-camera.ts
```ts
import { createArcRotateCamera } from "@babylonjs/lite/camera/arc-rotate.js";
import { attachControl } from "@babylonjs/lite/camera/arc-rotate-controls.js";
import { enableArcRotateKeyboardControls } from "@babylonjs/lite/camera/arc-rotate-keyboard-controls.js";
import type { ArcRotateCamera } from "@babylonjs/lite/camera/arc-rotate.js";
import type { SceneContext } from "@babylonjs/lite/scene/scene.js";

export function createOrbitCamera(canvas: HTMLCanvasElement, scene: SceneContext): ArcRotateCamera {
    const camera = createArcRotateCamera(0, Math.PI / 2, 10, { x: 0, y: 0, z: 0 });
    enableArcRotateKeyboardControls();
    attachControl(camera, canvas, scene, { keyboard: true });
    return camera;
}
```

I created `src/orbit-camera.ts` which builds an `ArcRotateCamera` at radius 10 targeting the origin, calls `enableArcRotateKeyboardControls()` (required per note 9 before `keyboard: true` is honoured), then attaches the standard pointer + keyboard controls via `attachControl`. The one thing I was not sure of is the exact subpath structure of the `@babylonjs/lite` package's exports — I inferred `@babylonjs/lite/camera/arc-rotate.js` etc. from the relative paths in the `.d.ts` files, but if the package uses a flat re-export from the root entry point the import specifiers would need adjusting.
